#tabs{gap:8px;left:24px;right:24px}#tabs div{font-size:21px;padding:9px 11px;border-width:3px} .row-c{display:flex;align-items:center;gap:20px;background:#fff;border:4px solid #16131C;box-shadow:8px 8px 0 #16131C;padding:12px 18px;margin-bottom:20px} .row-c .n{flex:none;width:64px;height:64px;background:#7C3AED;color:#fff;display:grid;place-items:center;font-weight:900;font-size:30px} .row-c .k{font-weight:900;font-size:30px;text-transform:uppercase;width:210px;flex:none} .chip{display:inline-block;border:3px solid #16131C;padding:6px 12px;font-weight:800;font-size:24px;margin-right:8px;background:#fff} .chip.on{background:#16131C;color:#fff} .url{display:flex;align-items:center;gap:14px;background:#fff;border:4px solid #16131C;box-shadow:8px 8px 0 #16131C;padding:14px 20px;font-weight:800;font-size:34px;margin:22px 0 26px} .url i{font-style:normal} .pay{background:#FFB300;color:#16131C;font-weight:900;font-size:28px;padding:10px 16px;border:3px solid #16131C;text-transform:uppercase} .bar{height:28px;border:4px solid #16131C;background:#fff;margin-top:18px;position:relative} .bar i{position:absolute;left:0;top:0;bottom:0;background:#7C3AED} .live{display:inline-block;background:#FF2D55;color:#fff;font-weight:900;font-size:40px;padding:8px 18px;border:4px solid #16131C} .brand{font-weight:900;font-size:110px;line-height:.95;letter-spacing:-3px;text-transform:uppercase} :root{--blue:#C13BE8;--violet:#8B5CF6;--grey:#6E7290;--line:#20243A}
html,body{background:#14172A;color:#fff} #stage{background-color:#14172A}
#caps .line{color:#fff} #caps .w{color:#6E7290} #caps .w.said{color:#fff} #caps .w.on{color:#FFC83D}
.title b,.brand-t b{background:linear-gradient(90deg,#9B3FE6,#E03AD6);-webkit-background-clip:text;background-clip:text;color:transparent}
.tag{background:linear-gradient(90deg,#9B3FE6,#E03AD6);color:#fff;border-radius:6px}
.card,.row-c,.url,.tile{color:#16131C;border-color:#0B0D18}
.card{box-shadow:12px 12px 0 #9B3FE6;border-radius:18px} .row-c,.url{box-shadow:8px 8px 0 #9B3FE6;border-radius:12px} .tile{box-shadow:8px 8px 0 #9B3FE6;border-radius:14px}
.row-c .n{background:linear-gradient(90deg,#9B3FE6,#E03AD6);border-radius:10px} .chip{border-radius:999px;border-color:#16131C} .chip.on{background:linear-gradient(90deg,#9B3FE6,#E03AD6);color:#fff;border-color:transparent}
#tabs div{background:#1E2238;color:#8A8DA8;border-color:#3A3F5C;border-radius:8px} #tabs div.on{background:linear-gradient(90deg,#9B3FE6,#E03AD6);color:#fff;box-shadow:none;border-color:transparent} #tabs div.done{color:#fff}
.who{background:linear-gradient(90deg,#9B3FE6,#E03AD6);border-radius:6px}
.btn{background:linear-gradient(90deg,#9B3FE6,#E03AD6);box-shadow:0 10px 30px rgba(224,58,214,.45);border-radius:999px}
.sticker{background:linear-gradient(90deg,#9B3FE6,#E03AD6);border-color:#fff;box-shadow:8px 8px 0 #FFC83D;border-radius:12px}
.think{color:#C13BE8} .bar i{background:linear-gradient(90deg,#9B3FE6,#E03AD6)} .pay{border-radius:999px}
.logo{display:flex;align-items:center;justify-content:center;gap:22px} .logo .ic2{width:120px;height:120px;border-radius:50%;background:linear-gradient(135deg,#6D5BF0,#E03AD6);display:grid;place-items:center;font-size:66px;box-shadow:0 0 0 6px #fff,0 0 0 10px #16131C}
.brand-t{font-weight:900;font-size:84px;line-height:.92;letter-spacing:-2px;text-transform:uppercase;text-align:left;color:#16131C}
.badge2{display:inline-block;border:2px solid #3A3F5C;background:#1E2238;color:#fff;border-radius:999px;padding:10px 20px;font-weight:800;font-size:28px} .chip{color:#16131C;background:#fff} .chip.on{color:#fff} #panel{container-type:size;background:radial-gradient(120% 80% at 50% 0%,#2A1F4E 0%,#14172A 60%);border-left:4px solid #9B3FE6;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:4.5cqw;padding:6cqw;color:#fff}
#panel .pl{display:flex;align-items:center;gap:3cqw;justify-content:center} #panel .pi{width:16cqw;height:16cqw;border-radius:50%;background:linear-gradient(135deg,#6D5BF0,#E03AD6);display:grid;place-items:center;font-size:9cqw;box-shadow:0 0 0 1cqw #fff}
#panel .pn{font-weight:900;font-size:11cqw;line-height:.9;text-transform:uppercase;text-align:left;letter-spacing:-.3cqw} #panel .pn b{background:linear-gradient(90deg,#9B3FE6,#E03AD6);-webkit-background-clip:text;background-clip:text;color:transparent}
#panel .ph{font-weight:900;font-size:8.2cqw;line-height:1.08;text-transform:uppercase} #panel .ph b{color:#FFC83D}
#panel .pc{display:flex;flex-wrap:wrap;gap:1.6cqw;justify-content:center} #panel .pc span{background:#fff;color:#16131C;border-radius:999px;font-weight:800;font-size:4.6cqw;padding:1.2cqw 3cqw}
#panel .pb{background:linear-gradient(90deg,#9B3FE6,#E03AD6);border-radius:999px;font-weight:900;font-size:6.4cqw;padding:3.4cqw 6cqw;box-shadow:0 1.5cqw 5cqw rgba(224,58,214,.5)} #panel .pb small{display:block;font-size:4.4cqw;font-weight:700;opacity:.95;text-transform:none}
#panel .pm{background:#FFB300;color:#16131C;border-radius:999px;font-weight:900;font-size:4.6cqw;padding:1.8cqw 3.6cqw} #panel .pp{font-weight:700;font-size:4.6cqw;color:#C9CBE0} #panel .px{display:none;font-weight:900;font-size:10cqw;line-height:1.05;text-transform:uppercase} #panel .px b{color:#FFC83D} @container (min-aspect-ratio: 1/1){ #panel>*{zoom:.62} #panel{gap:2.6cqh} }
@container (max-width: 400px){ #panel .ph,#panel .pc,#panel .pp{display:none} #panel{gap:7cqw} #panel .pl{flex-direction:column} #panel .pi{width:40cqw;height:40cqw;font-size:22cqw} #panel .pn{font-size:17cqw;text-align:center} #panel .pb{font-size:10cqw;padding:5cqw 6cqw;border-radius:6cqw} #panel .pb small{font-size:7.4cqw} #panel .pm{font-size:7cqw;border-radius:5cqw;line-height:1.3} #panel .px{display:block} }
.phone{zoom:1.42;width:640px;margin:40px auto 0;background:#fff;color:#16131C;border:8px solid #0B0D18;border-radius:54px;box-shadow:14px 14px 0 #9B3FE6;padding:26px 28px 34px;position:relative}
.phone .notch{width:160px;height:22px;background:#0B0D18;border-radius:0 0 16px 16px;margin:-26px auto 18px}
.phone .bar0{display:flex;align-items:center;gap:10px;background:#F1F1F6;border-radius:999px;padding:10px 18px;font-weight:700;font-size:24px;color:#555}
.phone .h{font-weight:900;font-size:36px;margin:18px 0 12px}
.phone .box{background:#F5F4FA;border-radius:18px;padding:18px 20px;margin-top:14px}
.phone .in{display:flex;gap:10px}.phone .in .f{flex:1;border:3px solid #9B3FE6;border-radius:16px;padding:12px 16px;font-family:monospace;font-weight:800;font-size:32px}
.phone .in .go{background:linear-gradient(90deg,#9B3FE6,#E03AD6);color:#fff;border-radius:16px;padding:12px 20px;font-weight:900;font-size:28px}
.st{display:flex;justify-content:space-between;text-align:center}.st div{flex:1;font-weight:800;font-size:24px;color:#9A97A8}
