.st .on{color:#16131C}.st .on i{background:linear-gradient(135deg,#9B3FE6,#E03AD6)}
.kv{display:flex;justify-content:space-between;font-weight:700;font-size:26px;color:#666;border-top:2px solid #E6E4EE;padding-top:12px;margin-top:14px}.kv b{color:#16131C}
.g3{display:grid;grid-template-columns:1fr 1fr 1fr;text-align:center}.g3 small{display:block;font-weight:700;font-size:22px;color:#777}.g3 span{font-weight:900;font-size:44px}
.pb2{height:22px;border-radius:999px;background:#E6E4EE;margin-top:16px;overflow:hidden}.pb2 i{display:block;height:100%;background:linear-gradient(90deg,#34D399,#10B981);border-radius:999px}
.ok{background:#ECFDF5;border:3px solid #A7F3D0;border-radius:18px;padding:18px;text-align:center;font-weight:900;font-size:36px;color:#065F46}
.live2{display:flex;align-items:center;justify-content:center;gap:10px;font-weight:700;font-size:24px;color:#777;margin-top:14px}.live2:before{content:'';width:14px;height:14px;border-radius:50%;background:#9B3FE6}
.tkt{border:3px solid #9B3FE6;background:#F7F0FF;color:#7C2BD6;border-radius:16px;padding:16px;text-align:center;font-weight:900;font-size:30px}
.povt{font-weight:900;font-size:64px;text-transform:uppercase;line-height:1.02;text-align:center}.povt b{color:#FFC83D}

.povt{font-size:84px}
